fn verifier_info() -> VerifierInfo {
    VerifierInfo {
        n_stages: 2,
        n_constants: 45,
        n_evals: 135,
        n_bits: 17,
        n_bits_ext: 20,
        arity: 4,
        n_fri_queries: 73,
        n_fri_steps: 6,
        n_challenges: 6,
        n_challenges_total: 13,
        fri_steps: vec![20, 17, 14, 11, 8, 5],
        hash_commits: true,
        last_level_verification: 2,
        pow_bits: 20,
        num_vals: vec![48, 12, 21],
        opening_points: vec![-2, -1, 0, 1, 2],
        boundaries: vec![Boundary { name: "everyRow".to_string(), offset_min: None, offset_max: None }],
        q_deg: 7,
        q_index: 102,
    }
}

pub fn verify(proof: &VadcopFinalProof, vk: &[u64]) -> bool {
    stark_verify::<Poseidon1_16, Poseidon1_16, Poseidon1_16, Poseidon1_8>(
        &proof.proof_with_publics(),
        vk,
        &verifier_info(),
        q_verify,
        query_verify,
    )
}

pub fn verify_u64(proof: &[u64], vk: &[u64]) -> bool {
    stark_verify::<Poseidon1_16, Poseidon1_16, Poseidon1_16, Poseidon1_8>(
        proof,
        vk,
        &verifier_info(),
        q_verify,
        query_verify,
    )
}

pub fn expected_proof_bytes() -> usize {
    crate::expected_proof_size_bytes(&verifier_info())
}
